[data-workspace-area="conversation"]::after{background:radial-gradient(70% 55% at 50% 100%,var(--sx-lava),transparent 72%);opacity:0}
:root:has(.chat-markdown[data-streaming],.live-tool-shine) [data-workspace-area="conversation"]::after{opacity:1}
